def longestLimitedConsonants(s, k):
    vowels = set("aeiou")
    left = 0
    cons = 0
    best = 0
    for right, ch in enumerate(s):
        if ch not in vowels:
            cons += 1
        while cons > k:
            if s[left] not in vowels:
                cons -= 1
            left += 1
        best = max(best, right - left + 1)
    return best
